import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.SLwxmuMO.js";var i=JSON.parse(`{"title":"Native Helper May Manipulate Targets","description":"","frontmatter":{"id":"decision.0006","title":"Native Helper May Manipulate Targets","status":"accepted","established-by":"user.2026-11-07","supersedes":["decision.0003"]},"headers":[],"relativePath":"decisions/0006-native-helper-may-manipulate-targets.md","filePath":"decisions/0006-native-helper-may-manipulate-targets.md"}`),a={name:`decisions/0006-native-helper-may-manipulate-targets.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="native-helper-may-manipulate-targets" tabindex="-1">Native Helper May Manipulate Targets <a class="header-anchor" href="#native-helper-may-manipulate-targets" aria-label="Permalink to “Native Helper May Manipulate Targets”">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>Withdraws decision.0003. Recon&#39;s native helper may manipulate the application it runs in as well as inspect it. What each helper operation does is decided by the proposal that adds it, not by a standing record of the helper&#39;s current scope.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><a href="./0003-recon-owned-native-loader">decision.0003</a> recorded the native loader and helper as <a href="./../proposals/0005-native-macos-inspection">proposal.0005</a> built them, including that &quot;the helper exposes only authenticated, bounded inspection operations&quot;. That sentence described the tool when it was written. <a href="./../proposals/0007-macos-ui-interaction">proposal.0007</a> then needed the helper to make a Mac Catalyst window key inside UIKit, because Catalyst ignores key chords until UIKit has a key window and nothing outside the process could set it. Read as a decision, the record forbade any helper operation that changes the target.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Recon does not limit its native helper to inspection. The helper may inspect and manipulate the application it runs in. Each operation, and how the loader and helper deliver it, is specified and approved by the proposal that adds or changes it, and is held to the active policies, including <a href="./../policies/0005-ui-no-interruption">policy.0005</a> and <a href="./../policies/0001-cli-command-and-error-contract">policy.0001</a>. decision.0003 no longer constrains the loader or the helper; their current design is described by proposal.0005 and the code.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to “Rationale”">​</a></h2><p>A record that describes a component&#39;s current scope turns every extension of it into a conflict with a commitment nobody made. Whether a given manipulation is appropriate depends on what it does, which only the proposal that adds it can show. The owner considers manipulating the target squarely within the helper&#39;s purpose.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><ul><li>Revise decision.0003 to allow one interaction operation for Catalyst key chords — keeps the inspection-only framing and makes every later manipulation another exception.</li><li>Replace decision.0003 with a record that keeps its loader guarantees as standing constraints — the owner chose to withdraw the record rather than preserve parts of it as intent.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="good" tabindex="-1">Good <a class="header-anchor" href="#good" aria-label="Permalink to “Good”">​</a></h3><ul><li>Helper operations that change the target, starting with proposal.0007&#39;s Catalyst key-window operation, are proposed and reviewed on their merits.</li><li>Records stop presenting the current implementation as intent.</li></ul><h3 id="bad" tabindex="-1">Bad <a class="header-anchor" href="#bad" aria-label="Permalink to “Bad”">​</a></h3><ul><li>No standing record bounds what the helper may do inside a target; each proposal that extends it must justify the authority it adds, and its review must check that justification.</li><li>The loader&#39;s incarnation checks and the helper&#39;s authenticated, bounded protocol are no longer protected by a decision record, so a proposal could change them without a record conflict, and reviews must notice when one does.</li></ul><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Authority</th></tr></thead><tbody><tr><td>2026-11-07</td><td>Accepted, superseding and withdrawing decision.0003.</td><td>Owner direction</td></tr></tbody></table>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};